+// #1394 manager-only: exact sparse candidate; all other roots retain the original guard.
+const KEY_SUBSET_ROOT = "/Users/silencehan/Projects/NewChanlun-1394-key-subset-20261002";
+const KEY_SUBSET_HEAD = "dd43fe07372da3ba4181fb23eaaa4e48d19f40c5";
+const KEY_SUBSET_SPARSE_SHA = "59541e27bdb899b6ea354c19505fd1dfc024ee5f6f01ca2e6f0ea0950a22589e";
+export function assertKeySubsetSparse(root: string, entries: string[]): void {
+  const hidden = entries.filter((entry) => entry[0] === "S" || /^[a-z]$/.test(entry[0]));
+  if (root !== KEY_SUBSET_ROOT) {
+    if (hidden.length) throw new Error(`checkout 含隐藏索引标志（${hidden.length} 项）`);
+    return;
+  }
+  if (git(root, ["rev-parse", "HEAD"]) !== KEY_SUBSET_HEAD ||
+      git(root, ["config", "--get", "core.sparseCheckout"]) !== "true" ||
+      git(root, ["config", "--get", "core.sparseCheckoutCone"]) !== "true") {
+    throw new Error("#1394 sparse HEAD/config 不匹配");
+  }
+  const rules = git(root, ["rev-parse", "--git-path", "info/sparse-checkout"]);
+  if (createHash("sha256").update(readFileSync(rules)).digest("hex") !== KEY_SUBSET_SPARSE_SHA) {
+    throw new Error("#1394 sparse rules SHA 不匹配");
+  }
+  if (hidden.some((entry) => /^[a-z]$/.test(entry[0]))) throw new Error("#1394 拒绝小写隐藏标志");
+  const skipped = hidden.filter((entry) => entry[0] === "S").map((entry) => entry.slice(2));
+  if (!skipped.length) return;
+  // This Git uses stdin by default; --stdin is unsupported. -z preserves exact filenames.
+  const included = execFileSync("git", ["-C", root, "sparse-checkout", "check-rules", "-z"], {
+    input: skipped.join("\0") + "\0", encoding: "utf8", stdio: ["pipe", "pipe", "pipe"],
+    env: { ...process.env, GIT_OPTIONAL_LOCKS: "0" },
+  });
+  if (included.length) throw new Error("#1394 included路径含 skip-worktree 标志");
+  for (const path of skipped) {
+    try { lstatSync(join(root, path)); } catch (error) {
+      if ((error as NodeJS.ErrnoException).code === "ENOENT") continue;
+      throw error;
+    }
+    throw new Error("#1394 excluded路径有磁盘实体或软链");
+  }
 }

